def split(line):
    out = []
    cur = ''
    started = False  # a word has begun (so quoted empty strings count as words)
    mode = None      # None, "'" or '"' while inside a quoted section
    i = 0
    n = len(line)
    while i < n:
        ch = line[i]
        if mode == "'":
            # Inside single quotes every character is literal until the close.
            if ch == "'":
                mode = None
            else:
                cur += ch
            i += 1
        elif mode == '"':
            if ch == '"':
                mode = None
                i += 1
            elif ch == '\\' and i + 1 < n and line[i + 1] in ('"', '\\'):
                # Backslash before a double quote or another backslash
                # yields that one character.
                cur += line[i + 1]
                i += 2
            else:
                # Any other backslash is kept as it is.
                cur += ch
                i += 1
        else:
            if ch == "'":
                mode = "'"
                started = True
                i += 1
            elif ch == '"':
                mode = '"'
                started = True
                i += 1
            elif ch == '\\':
                if i + 1 < n:
                    # Outside quotes a backslash makes the next character literal.
                    cur += line[i + 1]
                    i += 2
                else:
                    # A backslash at the very end of the line is kept.
                    cur += ch
                    i += 1
                started = True
            elif ch.isspace():
                if started:
                    out.append(cur)
                    cur = ''
                    started = False
                i += 1
            else:
                cur += ch
                started = True
                i += 1
    if mode is not None:
        raise ValueError('unterminated quote')
    if started:
        out.append(cur)
    return out

